import { Card, cardsStr, handClass, mulberry32, rankOf } from "./cards";
import { CALL_OPEN_TEXT, BB_DEFEND_TEXT, CALL_THREE_BET_TEXT, FOUR_BET_TEXT, LIMP_TEXT, RFI_TEXT, THREE_BET_TEXT, chart, chartPos, openerGroup } from "./charts";
import { CATEGORY, categoryOf, evaluate, findDraws } from "./evaluator";
import { POSTFLOP_ORDER, assignPositions, parseHand } from "./parser";
import { analyzeHand } from "./analyze";

/**
 * A demo session generated by a small seeded simulator, so the leak report can be shown without a file.
 *
 * How it is made: six players at a 6-max table, a fresh shuffle per hand from a fixed seed, and the
 * button moving one seat each hand. Villains play the app's own preflop charts and a simple strength-based
 * postflop policy. Hero plays the charts too, with four leaks built in so the report has something to find:
 * - calls opens too wide with offsuit broadways and weak suited aces,
 * - folds too much to 3-bets,
 * - folds medium-strength hands to river bets,
 * - calls river bets with busted draws and high cards about a third of the time.
 * The tournament hands (6 to 15bb, with antes) add a too-tight shoving range.
 * Postflop pots are kept heads-up and rake is zero, which keeps the generator short. One hand is deliberately
 * truncated so the import shows how a bad hand is reported. The output is a pure function of the seed.
 */
export const SAMPLE_SESSION_SEED = 20261113;
export const SAMPLE_CASH_HANDS = 200;
export const SAMPLE_TOURNAMENT_HANDS = 10;

const NAMES = ["riverrat_88", "NitNancy", "c0ldcall", "Hero", "bluffy_mcb", "TiltedTom"];
const T_NAMES = ["icm_ian", "chipleader_cho", "foldbot", "Hero", "sb_sam", "short_shover"];

const inChart = (text: string, cls: string) => (chart(text).get(cls) ?? 0) > 0;

// Hero's leaky extras, on top of the chart ranges.
export const HERO_LOOSE_CALL_TEXT = "KTo+, QTo+, JTo, A2s+, K9s+, Q9s+";
const HERO_SHOVE = "22+, A7s+, A9o+, KTs+, KQo, QJs";
const HERO_CALL_SHOVE = "77+, ATs+, AJo+, KQs";
const VILLAIN_SHOVE = "22+, A2s+, A7o+, K9s+, KTo+, QTs+, JTs";
const VILLAIN_CALL_SHOVE = "55+, A8s+, ATo+, KQs";
const CALL_FOUR_BET = "QQ+, AKs, AKo";

export type Strength = "strong" | "medium" | "draw" | "air";

/**
 * How the simulated hero plays. The sample session uses `LEAKY_HERO`; the integrity lab varies it to
 * make synthetic humans, a player using real-time assistance, and a bot.
 */
export interface HeroStyle {
  /** Hands hero calls an open with on top of the chart. Empty for none. */
  looseCall: string;
  /** Hero's range for calling a 3-bet, or null to use the chart. */
  callThreeBet: string | null;
  /** Chance hero folds a medium-strength hand to a river bet. */
  riverFoldMedium: number;
  /** Chance hero calls a river bet with nothing. */
  riverCallAir: number;
  /** Chance hero calls a flop or turn bet with nothing. */
  callAir: number;
  /** Hero's postflop bet as a fraction of the pot. Without it hero sizes like everyone else. */
  betSize?: (strength: Strength, rng: () => number) => number;
  /**
   * When set, hero asks the analysis engine before every call or fold facing a postflop bet and takes
   * the action with the higher EV against the engine's assumed range, as real-time assistance would.
   */
  engine?: boolean;
}

export const LEAKY_HERO: HeroStyle = { looseCall: HERO_LOOSE_CALL_TEXT, callThreeBet: "JJ-TT", riverFoldMedium: 1, riverCallAir: 0.35, callAir: 0.35 };

/** A rough strength bucket for the simulated players. Not used by the analysis, only to generate plausible play. */
function strength(hole: Card[], board: Card[]): Strength {
  const cat = categoryOf(evaluate([...hole, ...board]));
  const ranks = board.map(rankOf).sort((a, b) => b - a);
  const h = hole.map(rankOf);
  const pocket = h[0] === h[1];
  const connects = pocket || h.some((r) => ranks.includes(r));
  if (cat >= CATEGORY.STRAIGHT) return "strong";
  if (cat >= CATEGORY.TWO_PAIR) return connects ? "strong" : "medium";
  if (cat === CATEGORY.PAIR && connects) {
    if (pocket) return h[0] > ranks[0] ? "strong" : "medium";
    return h.includes(ranks[0]) ? "strong" : "medium";
  }
  if (board.length < 5) {
    const d = findDraws(hole, board);
    if (d.flushDraw || d.straightOutRanks >= 2) return "draw";
  }
  return "air";
}

interface Seat {
  seat: number;
  name: string;
  stack: number;
  position: string;
  hole: Card[];
}

interface Spec {
  id: number;
  tournament: boolean;
  button: number;
  rng: () => number;
  style: HeroStyle;
}

/** Simulates one hand and returns its PokerStars text. Amounts are integers: cents for cash, chips for tournaments. */
function simulate({ id, tournament, button, rng, style }: Spec): string {
  const sb = tournament ? 100 : 50;
  const bb = tournament ? 200 : 100;
  const ante = tournament ? 25 : 0;
  const fmt = (x: number) => (tournament ? String(x) : x % 100 === 0 ? `$${x / 100}` : `$${(x / 100).toFixed(2)}`);
  const names = tournament ? T_NAMES : NAMES;

  const deck = Array.from({ length: 52 }, (_, i) => i);
  for (let i = deck.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [deck[i], deck[j]] = [deck[j], deck[i]];
  }
  const positions = assignPositions([1, 2, 3, 4, 5, 6], button);
  const seats: Seat[] = names.map((name, i) => {
    const stackBb = tournament ? 6 + Math.floor(rng() * 10) : name === "Hero" ? 100 : 80 + Math.floor(rng() * 70);
    return { seat: i + 1, name, stack: stackBb * bb + (tournament ? 0 : Math.floor(rng() * 4) * 25), position: positions[i + 1], hole: [deck[2 * i], deck[2 * i + 1]] };
  });
  const board = deck.slice(12, 17);
  const by = (name: string) => seats.find((s) => s.name === name)!;
  const hero = by("Hero");

  const lines: string[] = [];
  const date = `2026/11/${String(10 + (id % 3)).padStart(2, "0")} ${20 + (id % 3)}:${String(id % 60).padStart(2, "0")}:00 ET`;
  lines.push(
    tournament
      ? `PokerStars Hand #26111${String(id).padStart(7, "0")}: Tournament #3999000222, $10+$1 USD Hold'em No Limit - Level V (${sb}/${bb}) - ${date}`
      : `PokerStars Hand #26110${String(id).padStart(7, "0")}:  Hold'em No Limit ($0.50/$1.00 USD) - ${date}`,
  );
  lines.push(tournament ? `Table '3999000222 7' 6-max Seat #${button} is the button` : `Table 'Sample Session' 6-max Seat #${button} is the button`);
  for (const s of seats) lines.push(`Seat ${s.seat}: ${s.name} (${fmt(s.stack)} in chips)`);

  const stacks: Record<string, number> = Object.fromEntries(seats.map((s) => [s.name, s.stack]));
  const invested: Record<string, number> = Object.fromEntries(seats.map((s) => [s.name, 0]));
  let committed: Record<string, number> = Object.fromEntries(seats.map((s) => [s.name, 0]));
  const folded = new Set<string>();
  const allIn = new Set<string>();
  let currentBet = 0;

  const put = (name: string, amount: number) => {
    const x = Math.min(amount, stacks[name]);
    stacks[name] -= x;
    invested[name] += x;
    committed[name] += x;
    if (stacks[name] === 0) allIn.add(name);
    return x;
  };
  const ai = (name: string) => (allIn.has(name) ? " and is all-in" : "");

  const preOrder = ["UTG", "UTG+1", "MP", "LJ", "HJ", "CO", "BTN", "SB", "BB"];
  const ordered = [...seats].sort((a, b) => preOrder.indexOf(a.position) - preOrder.indexOf(b.position));
  if (ante) for (const s of seats) {
    put(s.name, ante);
    lines.push(`${s.name}: posts the ante ${fmt(ante)}`);
  }
  committed = Object.fromEntries(seats.map((s) => [s.name, 0]));
  const sbSeat = seats.find((s) => s.position === "SB")!;
  const bbSeat = seats.find((s) => s.position === "BB")!;
  lines.push(`${sbSeat.name}: posts small blind ${fmt(put(sbSeat.name, sb))}`);
  lines.push(`${bbSeat.name}: posts big blind ${fmt(put(bbSeat.name, bb))}`);
  currentBet = bb;
  lines.push("*** HOLE CARDS ***", `Dealt to Hero [${cardsStr(hero.hole)}]`);

  const act = {
    fold: (n: string) => {
      folded.add(n);
      lines.push(`${n}: folds`);
    },
    check: (n: string) => lines.push(`${n}: checks`),
    call: (n: string) => {
      const x = put(n, currentBet - committed[n]);
      lines.push(`${n}: calls ${fmt(x)}${ai(n)}`);
    },
    bet: (n: string, amount: number) => {
      const x = put(n, amount);
      currentBet = committed[n];
      lines.push(`${n}: bets ${fmt(x)}${ai(n)}`);
    },
    raiseTo: (n: string, to: number) => {
      const target = Math.min(to, committed[n] + stacks[n]);
      const by = target - currentBet;
      put(n, target - committed[n]);
      currentBet = committed[n];
      lines.push(`${n}: raises ${fmt(by)} to ${fmt(target)}${ai(n)}`);
    },
  };

  // ------------------------------------------------ preflop
  let raises = 0;
  let limpers = 0;
  let aggressor: string | null = null;
  let opener: string | null = null;
  const live = () => seats.filter((s) => !folded.has(s.name));
  const short = (n: string) => (stacks[n] + invested[n]) / bb <= 15;

  const decide = (s: Seat): "fold" | "check" | "call" | "raise" | "shove" => {
    const cls = handClass(s.hole[0], s.hole[1]);
    const isHero = s.name === "Hero";
    const toCall = currentBet - committed[s.name];
    if (tournament && short(s.name)) {
      if (raises === 0 && limpers === 0) {
        if (s.position === "BB") return "check";
        return inChart(isHero ? HERO_SHOVE : VILLAIN_SHOVE, cls) ? "shove" : "fold";
      }
      return inChart(isHero ? HERO_CALL_SHOVE : VILLAIN_CALL_SHOVE, cls) ? "call" : "fold";
    }
    if (raises === 0) {
      if (limpers > 0) {
        if (inChart(RFI_TEXT.UTG, cls)) return "raise";
        if (toCall === 0) return "check";
        return isHero || s.name !== "c0ldcall" ? "fold" : inChart(LIMP_TEXT, cls) ? "call" : "fold";
      }
      if (s.position === "BB") return "check";
      if (inChart(RFI_TEXT[chartPos(s.position)], cls)) return "raise";
      // c0ldcall limps a lot; hero completes the small blind with limping hands.
      if ((s.name === "c0ldcall" || (isHero && s.position === "SB")) && inChart(LIMP_TEXT, cls)) return "call";
      return "fold";
    }
    if (raises === 1) {
      const g = openerGroup(by(opener!).position);
      if (inChart(THREE_BET_TEXT[g], cls)) return "raise";
      if (inChart(s.position === "BB" ? BB_DEFEND_TEXT[g] : CALL_OPEN_TEXT[g], cls)) return "call";
      if (isHero && style.looseCall && inChart(style.looseCall, cls)) return "call";
      return "fold";
    }
    if (raises === 2) {
      if (inChart(FOUR_BET_TEXT, cls)) return "shove";
      if (isHero && style.callThreeBet !== null) return inChart(style.callThreeBet, cls) ? "call" : "fold";
      return inChart(CALL_THREE_BET_TEXT, cls) ? "call" : "fold";
    }
    return inChart(CALL_FOUR_BET, cls) ? "call" : "fold";
  };

  // Each player acts in turn until everyone still able to act has matched the bet. To keep every flop heads-up,
  // once a raise has been called, or once there have been two raises, players outside that pair fold.
  // Limping is allowed for one player only, and only the big blind can check behind it.
  let i = 0;
  const acted = new Set<string>();
  let caller: string | null = null;
  while (live().length > 1 && i < 80) {
    const canAct = live().filter((p) => !allIn.has(p.name));
    const pending = canAct.filter((p) => !acted.has(p.name) || committed[p.name] < currentBet);
    if (!pending.length) break;
    const s = ordered[i % ordered.length];
    i++;
    if (!pending.includes(s)) continue;
    const toCall = currentBet - committed[s.name];
    const outsider = s.name !== aggressor && s.name !== opener && s.name !== caller;
    if (((caller && raises > 0) || raises >= 2) && outsider) {
      act.fold(s.name);
      continue;
    }
    let choice = decide(s);
    // With nobody else holding chips there is nothing to raise against.
    const othersWithChips = live().filter((p) => p.name !== s.name && !allIn.has(p.name)).length;
    if ((choice === "raise" || choice === "shove") && othersWithChips === 0) choice = "call";
    if (choice === "call" && raises === 0 && limpers > 0 && s.position !== "BB") choice = "fold";
    if (choice === "check" && toCall > 0) choice = "fold";
    if (choice === "call" && toCall === 0) choice = "check";
    let to = 0;
    if (choice === "raise" || choice === "shove") {
      to =
        choice === "shove"
          ? committed[s.name] + stacks[s.name]
          : raises === 0
            ? (limpers > 0 ? 4 + limpers : s.position === "SB" ? 3 : 2.5) * bb
            : Math.round(currentBet * (s.position === "SB" || s.position === "BB" ? 3.5 : 3));
      if (Math.min(to, committed[s.name] + stacks[s.name]) <= currentBet) choice = toCall > 0 ? "call" : "check";
    }
    acted.add(s.name);
    if (choice === "fold") act.fold(s.name);
    else if (choice === "check") act.check(s.name);
    else if (choice === "call") {
      act.call(s.name);
      if (raises === 0) limpers++;
      else caller = s.name;
    } else {
      act.raiseTo(s.name, to);
      if (raises === 0) opener = s.name;
      raises++;
      aggressor = s.name;
      caller = null;
    }
  }

  const returnUncalled = () => {
    const remaining = live();
    if (remaining.length === 1) {
      const w = remaining[0].name;
      const others = Math.max(0, ...seats.filter((s) => s.name !== w).map((s) => committed[s.name]));
      const back = committed[w] - others;
      if (back > 0) {
        stacks[w] += back;
        invested[w] -= back;
        committed[w] -= back;
        lines.push(`Uncalled bet (${fmt(back)}) returned to ${w}`);
      }
      return w;
    }
    // Two players left and one is all-in for less: return the excess to the bigger stack.
    const [a, b] = remaining.map((s) => s.name).sort((x, y) => invested[y] - invested[x]);
    const back = invested[a] - invested[b];
    if (back > 0 && allIn.has(b)) {
      stacks[a] += back;
      invested[a] -= back;
      committed[a] -= back;
      lines.push(`Uncalled bet (${fmt(back)}) returned to ${a}`);
    }
    return null;
  };

  const finish = (winner: string | null) => {
    const pot = Object.values(invested).reduce((x, y) => x + y, 0);
    if (winner) {
      lines.push(`${winner} collected ${fmt(pot)} from pot`);
    } else {
      const [a, b] = live();
      lines.push("*** SHOW DOWN ***");
      const score = (s: Seat) => evaluate([...s.hole, ...board]);
      lines.push(`${a.name}: shows [${cardsStr(a.hole)}]`, `${b.name}: shows [${cardsStr(b.hole)}]`);
      const sa = score(a), sb2 = score(b);
      if (sa === sb2) {
        const half = Math.floor(pot / 2);
        lines.push(`${a.name} collected ${fmt(pot - half)} from pot`, `${b.name} collected ${fmt(half)} from pot`);
      } else lines.push(`${(sa > sb2 ? a : b).name} collected ${fmt(pot)} from pot`);
    }
    lines.push("*** SUMMARY ***", `Total pot ${fmt(pot)} | Rake ${fmt(0)}`);
    if (!winner) lines.push(`Board [${cardsStr(board)}]`);
    return lines.join("\n");
  };

  let w = returnUncalled();
  if (w) return finish(w);

  // ------------------------------------------------ postflop, heads-up
  const [p1, p2] = live().sort((a, b) => POSTFLOP_ORDER.indexOf(a.position) - POSTFLOP_ORDER.indexOf(b.position));
  const streets: [string, number][] = [["FLOP", 3], ["TURN", 4], ["RIVER", 5]];
  for (const [label, n] of streets) {
    const shown = board.slice(0, n);
    lines.push(n === 3 ? `*** FLOP *** [${cardsStr(shown)}]` : `*** ${label} *** [${cardsStr(board.slice(0, n - 1))}] [${cardsStr([board[n - 1]])}]`);
    committed = Object.fromEntries(seats.map((s) => [s.name, 0]));
    currentBet = 0;
    if (allIn.has(p1.name) || allIn.has(p2.name)) continue;
    const river = n === 5;
    const pot = () => Object.values(invested).reduce((x, y) => x + y, 0);

    const wantsBet = (s: Seat, isAggressor: boolean): number => {
      const st = strength(s.hole, shown);
      const r = rng();
      const sizes = s.name === "Hero" && style.betSize ? style.betSize(st, rng) : st === "strong" ? 0.66 : 0.5;
      let go = false;
      if (st === "strong") go = r < 0.85;
      else if (st === "medium") go = isAggressor && (n === 3 ? r < 0.6 : r < 0.3);
      else if (st === "draw") go = isAggressor ? r < 0.6 : r < 0.3;
      else go = isAggressor ? (n === 3 ? r < 0.55 : r < 0.4) : r < 0.3;
      return go ? Math.max(bb, Math.round((pot() * sizes) / (tournament ? 25 : 5)) * (tournament ? 25 : 5)) : 0;
    };
    const facing = (s: Seat): "call" | "fold" | "raise" => {
      const st = strength(s.hole, shown);
      const r = rng();
      const isHero = s.name === "Hero";
      if (st === "strong" && n === 3 && r < 0.15) return "raise";
      if (isHero && style.engine) return engineSaysCall() ? "call" : "fold";
      if (st === "strong") return "call";
      if (st === "medium") return river ? (isHero ? (r < style.riverFoldMedium ? "fold" : "call") : r < 0.5 ? "call" : "fold") : "call";
      if (st === "draw") return "call";
      if (river) return isHero && r < style.riverCallAir ? "call" : "fold";
      return r < (isHero ? style.callAir : 0.2) ? "call" : "fold";
    };

    // Real-time assistance: analyse the hand so far as if hero folded, and call when calling is worth more.
    const engineSaysCall = () => {
      const sofar = parseHand(`${lines.join("\n")}\nHero: folds`);
      const d = analyzeHand(sofar, { iterations: 1000 }).decisions.at(-1);
      return (d?.evCall ?? -1) > 0;
    };

    const bettor = (first: Seat, second: Seat): boolean => {
      // Returns true if the hand ended with a fold on this street.
      const amount = wantsBet(first, first.name === aggressor);
      if (!amount) {
        act.check(first.name);
        const back = wantsBet(second, true);
        if (!back) {
          act.check(second.name);
          return false;
        }
        act.bet(second.name, back);
        aggressor = second.name;
        return respond(first, second);
      }
      act.bet(first.name, amount);
      aggressor = first.name;
      return respond(second, first);
    };
    const respond = (s: Seat, bettorSeat: Seat): boolean => {
      const choice = facing(s);
      if (choice === "fold") {
        act.fold(s.name);
        return true;
      }
      if (choice === "raise" && stacks[s.name] > currentBet - committed[s.name]) {
        act.raiseTo(s.name, currentBet * 3);
        aggressor = s.name;
        if (strength(bettorSeat.hole, shown) === "strong") act.call(bettorSeat.name);
        else {
          act.fold(bettorSeat.name);
          return true;
        }
        return false;
      }
      act.call(s.name);
      return false;
    };

    if (bettor(p1, p2)) {
      w = returnUncalled();
      return finish(w);
    }
    returnUncalled();
  }
  return finish(null);
}

/** One deliberately broken hand: the header and seats are there but the hole cards line is missing. */
function brokenHand(): string {
  return `PokerStars Hand #261109999999:  Hold'em No Limit ($0.50/$1.00 USD) - 2026/11/12 23:59:00 ET
Table 'Sample Session' 6-max Seat #2 is the button
Seat 1: riverrat_88 ($100 in chips)
Seat 2: NitNancy ($100 in chips)
Seat 4: Hero ($100 in chips)
riverrat_88: posts small blind $0.50
NitNancy: posts big blind $1
*** HOLE CARDS ***
Hero: folds`;
}

/** The sample session as one PokerStars-format file. Deterministic for a given seed. */
export function makeSampleSession(seed = SAMPLE_SESSION_SEED): string {
  const rng = mulberry32(seed);
  const hands: string[] = [];
  for (let k = 0; k < SAMPLE_CASH_HANDS; k++) hands.push(simulate({ id: k + 1, tournament: false, button: (k % 6) + 1, rng, style: LEAKY_HERO }));
  for (let k = 0; k < SAMPLE_TOURNAMENT_HANDS; k++) hands.push(simulate({ id: k + 1, tournament: true, button: (k % 6) + 1, rng, style: LEAKY_HERO }));
  hands.splice(30, 0, brokenHand());
  return hands.join("\n\n\n");
}

/** Cash hands only, played by a hero with the given style. Deterministic for a given seed and style. */
export function makeStyledSession(style: HeroStyle, seed: number, hands = SAMPLE_CASH_HANDS): string {
  const rng = mulberry32(seed);
  const out: string[] = [];
  for (let k = 0; k < hands; k++) out.push(simulate({ id: k + 1, tournament: false, button: (k % 6) + 1, rng, style }));
  return out.join("\n\n\n");
}

let cached: string | null = null;
export function sampleSession(): string {
  return (cached ??= makeSampleSession());
}
